    SELECT 'AP' || LPAD(SEQ_APPT_NO.NEXTVAL, 8, '0') FROM DUAL

INSERT INTO TB_APPOINT (APPT_NO, EMP_NO, APPT_TYPE, FROM_DEPT_CD, TO_DEPT_CD, APPT_DT, STATUS, REG_DT, REG_ID)
SELECT #{apptNo}, E.EMP_NO, #{apptType}, E.DEPT_CD, #{toDeptCd}, REPLACE(#{apptDt}, '-', ''), #{status}, SYSDATE, #{regId}
  FROM TB_EMP E
 WHERE E.EMP_NO = #{empNo}

